const s = params.height / 4.2;
const iron = { preset: 'metal', color: params.ironColor, metalness: 0.6, roughness: 0.5 };
const brass = { preset: 'metal', color: params.brassColor, metalness: 0.8, roughness: 0.22, emissive: '#3a2605', emissiveIntensity: 0.4 };
const glass = { preset: 'emissive', color: params.glowColor, emissive: params.glowColor, emissiveIntensity: 2.2, opacity: 0.9 };
const flame = { preset: 'emissive', color: '#ffe080', emissive: '#ffd060', emissiveIntensity: 6 };
// plinth
api.add(api.cylinder(0.3*s, 0.32*s, 0.08*s, 8).translate(0, 0.04*s, 0), iron);
api.add(api.cylinder(0.25*s, 0.28*s, 0.06*s, 8).translate(0, 0.11*s, 0), iron);
// fluted base
const base = api.lathe([[0,0.14*s],[0.22*s,0.14*s],[0.23*s,0.2*s],[0.2*s,0.35*s],[0.17*s,0.55*s],[0.12*s,0.75*s],[0.09*s,0.88*s],[0.09*s,0.92*s],[0,0.92*s]], 16);
api.add(base, iron);
for (let i = 0; i < 8; i++) {
  const a = i / 8 * Math.PI * 2;
  const rib = api.cylinder(0.014*s, 0.03*s, 0.7*s, 6);
  rib.translate(0, 0.51*s, 0);
  // taper handled by cylinder radii; place at base surface
  rib.translate(Math.cos(a)*0.165*s, 0, Math.sin(a)*0.165*s);
  api.add(rib, iron);
}
api.add(api.cylinder(0.12*s, 0.1*s, 0.04*s, 16).translate(0, 0.94*s, 0), brass);
const postTop = 3.4 * s;
api.add(api.cylinder(0.045*s, 0.075*s, postTop - 0.95*s, 14).translate(0, (postTop + 0.95*s)/2, 0), iron);
const rr = [[0.95,0.095],[1.5,0.085],[3.2,0.062]];
for (const q of rr) api.add(api.cylinder(q[1]*s, q[1]*s, 0.04*s, 16).translate(0, q[0]*s, 0), brass);
api.add(api.sphere(0.08*s, 2).translate(0, 2.2*s, 0), iron);
// cross bar
api.add(api.cylinder(0.0125*s*1.6, 0.0125*s*1.6, 0.7*s, 8).rotate(0,0,90).translate(0, 3.0*s, 0), iron);
for (const sx of [-1, 1]) api.add(api.sphere(0.04*s, 3).translate(sx*0.35*s, 3.0*s, 0), brass);
// head
const hy = postTop, hh = 0.55 * s, hr = 0.2 * s;
const gy = hy + 0.08*s;
api.add(api.cylinder(0.22*s, 0.09*s, 0.08*s, 6).translate(0, hy + 0.04*s, 0), iron);
api.add(api.cylinder(hr, hr, hh, 6).translate(0, gy + hh/2, 0), glass);
api.add(api.sphere(0.075*s, 2).translate(0, gy + hh*0.45, 0), flame);
for (let i = 0; i < 6; i++) {
  const a = i / 6 * Math.PI * 2;
  api.add(api.box(0.04*s, hh + 0.02*s, 0.04*s).rotate(0, -a*180/Math.PI, 0).translate(Math.cos(a)*hr*1.02, gy + hh/2, -Math.sin(a)*hr*1.02), iron);
}
api.add(api.cylinder(0.22*s, 0.22*s, 0.03*s, 6).translate(0, gy + 0.015*s, 0), iron);
const top = gy + hh;
api.add(api.cylinder(0.23*s, 0.22*s, 0.03*s, 6).translate(0, top + 0.015*s, 0), brass);
const dome = api.lathe([[0,0],[0.27*s,0],[0.26*s,0.04*s],[0.2*s,0.11*s],[0.12*s,0.18*s],[0.05*s,0.23*s],[0,0.25*s]], 12).translate(0, top + 0.03*s, 0);
api.add(dome, iron);
api.add(api.sphere(0.05*s, 3).translate(0, top + 0.3*s, 0), brass);
api.add(api.cone(0.02*s, 0.12*s, 8).translate(0, top + 0.39*s, 0), brass);
api.collider({ kind: 'cylinder', radius: 0.3*s, halfHeight: 0.46*s, offset: [0, 0.46*s, 0] });
api.collider({ kind: 'cylinder', radius: 0.08*s, halfHeight: 2.1*s, offset: [0, 2.1*s, 0] });
return api.build();
